def atbash(s):
    out = ""
    for ch in s:
        if 'A' <= ch <= 'Z':
            out += chr(ord('Z') - (ord(ch) - ord('A')))
        elif 'a' <= ch <= 'z':
            out += chr(ord('z') - (ord(ch) - ord('a')))
        else:
            out += ch
    return out

print("M-C", "=>", atbash("M-C"))
print("L-B", "=>", atbash("L-B"))
